//! The grammar's vocabulary: node kinds, and the token classes, bracket
//! pairs, and operator tables the parser and the newline rule read.
//!
//! @generated by `cargo xtask codegen` from `sumi.grammar`; do not edit.

/// The language-level kind of a token, assigned by the fused lexer and
/// re-exported here where the grammar consumes it.
///
/// Kept separate from the tree's [`NodeKind`]: nodes cover ranges of
/// tokens rather than sitting among them, so the two vocabularies never
/// share a slot.
pub use sumi_lexer::SyntaxKind;

/// The typed views over the tree, generated beside this module.
pub mod ast;

/// The kind of a syntax tree node.
///
/// A node is structure only, so this vocabulary is disjoint from
/// [`SyntaxKind`]: a tree slot never holds a token kind, and a token
/// buffer slot never holds a node kind.
#[repr(u8)]
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum NodeKind {
    SourceFile,
    FnItem,
    ParamList,
    Param,
    /// A declaring occurrence of a name: what an item, a parameter, or a
    /// binding introduces. A use is a NameRef.
    Name,
    /// A type reference: a name, until types grow more shapes.
    TypeRef,
    Block,
    LetStmt,
    AssignStmt,
    DiscardStmt,
    ReturnStmt,
    /// A use of a name: a reference to what a Name declared.
    NameRef,
    LiteralExpr,
    PrefixExpr,
    BinaryExpr,
    ParenExpr,
    CallExpr,
    ArgList,
    IfExpr,
    /// Covers tokens the parser could not parse.
    Error,
}

/// Whether a token of this kind can begin an expression.
pub fn starts_expression(kind: SyntaxKind) -> bool {
    matches!(
        kind,
        SyntaxKind::Ident
            | SyntaxKind::FalseKw
            | SyntaxKind::IfKw
            | SyntaxKind::TrueKw
            | SyntaxKind::IntLiteral
            | SyntaxKind::FloatLiteral
            | SyntaxKind::StringLiteral
            | SyntaxKind::RawStringLiteral
            | SyntaxKind::BlockStringLiteral
            | SyntaxKind::RawBlockStringLiteral
            | SyntaxKind::CharLiteral
            | SyntaxKind::LParen
            | SyntaxKind::LBrace
            | SyntaxKind::Bang
            | SyntaxKind::Minus
    )
}

/// Whether a token of this kind begins a statement that is not an
/// expression: a declaration keyword, `_`, or an `Error` run.
pub fn introduces_statement(kind: SyntaxKind) -> bool {
    matches!(
        kind,
        SyntaxKind::Underscore | SyntaxKind::LetKw | SyntaxKind::ReturnKw | SyntaxKind::Error
    )
}

/// Whether a token of this kind can begin a statement.
pub fn starts_statement(kind: SyntaxKind) -> bool {
    introduces_statement(kind) || starts_expression(kind)
}

/// Whether a statement can end after a token of this kind: values and
/// closers can; operators, openers, and introducer keywords need more.
pub fn can_end_statement(kind: SyntaxKind) -> bool {
    matches!(
        kind,
        SyntaxKind::Ident
            | SyntaxKind::Underscore
            | SyntaxKind::FalseKw
            | SyntaxKind::ReturnKw
            | SyntaxKind::TrueKw
            | SyntaxKind::IntLiteral
            | SyntaxKind::FloatLiteral
            | SyntaxKind::StringLiteral
            | SyntaxKind::RawStringLiteral
            | SyntaxKind::BlockStringLiteral
            | SyntaxKind::RawBlockStringLiteral
            | SyntaxKind::CharLiteral
            | SyntaxKind::RParen
            | SyntaxKind::RBrace
            | SyntaxKind::Error
    )
}

/// Whether a token of this kind begins a top-level item.
pub fn starts_item(kind: SyntaxKind) -> bool {
    matches!(kind, SyntaxKind::FnKw)
}

/// Whether a token of this kind is a prefix operator.
pub fn is_prefix_operator(kind: SyntaxKind) -> bool {
    matches!(kind, SyntaxKind::Minus | SyntaxKind::Bang)
}

/// Whether a token of this kind continues a statement left open on the
/// previous line; `glued` is the kind of the token glued after it, if
/// any.
///
/// Continuation tokens can never start a statement: the keywords declared
/// to continue, and the binary operators — a compound one only when glued
/// into shape, and one that is also a prefix operator only when spaced
/// from what follows, since glued it opens an operand instead.
pub fn continues_statement(kind: SyntaxKind, glued: Option<SyntaxKind>) -> bool {
    match kind {
        SyntaxKind::ElseKw
        | SyntaxKind::Lt
        | SyntaxKind::Gt
        | SyntaxKind::Plus
        | SyntaxKind::Star
        | SyntaxKind::Slash
        | SyntaxKind::Percent => true,
        SyntaxKind::Eq | SyntaxKind::Bang => matches!(glued, Some(SyntaxKind::Eq)),
        SyntaxKind::Minus => glued.is_none(),
        SyntaxKind::Amp => matches!(glued, Some(SyntaxKind::Amp)),
        SyntaxKind::Pipe => matches!(glued, Some(SyntaxKind::Pipe)),
        _ => false,
    }
}

/// The bracket pairs the token stream matches, opener then closer.
pub const BRACKET_PAIRS: [(SyntaxKind, SyntaxKind); 2] = [
    (SyntaxKind::LParen, SyntaxKind::RParen),
    (SyntaxKind::LBrace, SyntaxKind::RBrace),
];

/// The closer pairing with an opener of this kind.
pub fn closer(opener: SyntaxKind) -> Option<SyntaxKind> {
    Some(match opener {
        SyntaxKind::LParen => SyntaxKind::RParen,
        SyntaxKind::LBrace => SyntaxKind::RBrace,
        _ => return None,
    })
}

/// The opener pairing with a closer of this kind.
pub fn opener(closer: SyntaxKind) -> Option<SyntaxKind> {
    Some(match closer {
        SyntaxKind::RParen => SyntaxKind::LParen,
        SyntaxKind::RBrace => SyntaxKind::LBrace,
        _ => return None,
    })
}

/// Whether a token of this kind opens a bracket pair.
pub fn is_opener(kind: SyntaxKind) -> bool {
    closer(kind).is_some()
}

/// Whether a token of this kind closes a bracket pair.
pub fn is_closer(kind: SyntaxKind) -> bool {
    opener(kind).is_some()
}

/// Whether a token of this kind opens or closes a bracket pair.
pub fn is_bracket(kind: SyntaxKind) -> bool {
    is_opener(kind) || is_closer(kind)
}

/// Whether the pair opened by this kind encloses statements, so that line
/// breaks inside it end statements as a block's do. Every other pair
/// suspends the newline rule between its brackets.
pub fn encloses_statements(opener: SyntaxKind) -> bool {
    matches!(opener, SyntaxKind::LBrace)
}

/// The binding power of a prefix operator's operand: tighter than every
/// binary operator, so only a call binds closer.
pub const PREFIX_BP: u8 = 11;

/// A binary operator.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum BinaryOp {
    /// `||`
    Or,
    /// `&&`
    And,
    /// `==`
    Eq,
    /// `!=`
    Ne,
    /// `<`
    Lt,
    /// `<=`
    Le,
    /// `>`
    Gt,
    /// `>=`
    Ge,
    /// `+`
    Add,
    /// `-`
    Sub,
    /// `*`
    Mul,
    /// `/`
    Div,
    /// `%`
    Rem,
}

impl BinaryOp {
    /// Left and right binding powers. Every operator associates left, so
    /// it binds tighter on the right; comparisons too, so a chain parses
    /// left to right and is then rejected.
    pub fn binding_power(self) -> (u8, u8) {
        match self {
            Self::Or => (1, 2),
            Self::And => (3, 4),
            Self::Eq | Self::Ne | Self::Lt | Self::Le | Self::Gt | Self::Ge => (5, 6),
            Self::Add | Self::Sub => (7, 8),
            Self::Mul | Self::Div | Self::Rem => (9, 10),
        }
    }

    /// Whether the operator is a comparison, which does not chain.
    pub fn is_comparison(self) -> bool {
        matches!(
            self,
            Self::Eq | Self::Ne | Self::Lt | Self::Le | Self::Gt | Self::Ge
        )
    }
}

/// The binary operator a token of kind `first` begins, and its width in
/// tokens; `glued` is the kind of the token glued after it, if any. A
/// compound operator is its tokens glued; a lone `=` is no operator.
pub fn binary_operator(first: SyntaxKind, glued: Option<SyntaxKind>) -> Option<(BinaryOp, usize)> {
    Some(match first {
        SyntaxKind::Pipe if glued == Some(SyntaxKind::Pipe) => (BinaryOp::Or, 2),
        SyntaxKind::Amp if glued == Some(SyntaxKind::Amp) => (BinaryOp::And, 2),
        SyntaxKind::Eq if glued == Some(SyntaxKind::Eq) => (BinaryOp::Eq, 2),
        SyntaxKind::Bang if glued == Some(SyntaxKind::Eq) => (BinaryOp::Ne, 2),
        SyntaxKind::Lt if glued == Some(SyntaxKind::Eq) => (BinaryOp::Le, 2),
        SyntaxKind::Gt if glued == Some(SyntaxKind::Eq) => (BinaryOp::Ge, 2),
        SyntaxKind::Lt => (BinaryOp::Lt, 1),
        SyntaxKind::Gt => (BinaryOp::Gt, 1),
        SyntaxKind::Plus => (BinaryOp::Add, 1),
        SyntaxKind::Minus => (BinaryOp::Sub, 1),
        SyntaxKind::Star => (BinaryOp::Mul, 1),
        SyntaxKind::Slash => (BinaryOp::Div, 1),
        SyntaxKind::Percent => (BinaryOp::Rem, 1),
        _ => return None,
    })
}
